#include<bits/stdc++.h>

using namespace std;

int main(){
  int n,m;
  cin >> n >> m;
  vector<int> S(m+1,0);
  vector<int> C(m+1,0);
  for(int i=0;i<n;i++){
    int a,b;
    cin >> a >> b;
    S[a]+=b;
    C[a]++;
  }
  for(int i=1;i<=m;i++){
    double oup=S[i];
    oup/=C[i];
    cout << fixed << setprecision(12) << oup << "\n";
  }
  return 0;
}
